        conditionsStability: "Estabilidad",
        conditionsFormulaApprovalHigh: (a, b) => `Aprobación = felicidad = ${a}. Por encima de 50: +0,6 × (${a} − 50), redondeado hacia abajo = ${b}`,
        conditionsFormulaApprovalLow: (a, b) => `Aprobación = felicidad = ${a}. Por debajo de 50: −1 × (50 − ${a}) = ${b}`,
        conditionsFormulaHousing: (m, r, p) => `Vivienda: −40 × faltante / necesaria = −40 × ${m} / ${r} = ${p}`,
        conditionsInfoStability: "Estabilidad: parte de 50 (de 0 a 100). En un imperio normal suma 0,6 por cada punto de aprobación por encima de 50 y resta 1 por cada punto por debajo; aquí la aprobación es igual a la felicidad porque todos los pops se tratan igual. En un imperio gestalt no hay felicidad: los servicios actúan directamente sobre la estabilidad con las mismas cifras. Empleos como policías y soldados suman su estabilidad (un modificador, así que el efecto de la estabilidad no la cambia). Si falta alojamiento, resta 40 × (alojamiento que falta / necesario). El crimen se muestra pero no cambia la estabilidad; los edictos, facciones y eventos no se modelan (usa la estabilidad extra manual).",
        conditionsHappinessBase: "Felicidad base",
