        conditionsFormulaBonus: (a, u, r, e) => `Surplus amenities: min(20, 20 × ${a} / ${u}) = min(20, ${r}) = ${e}`,
        conditionsFormulaPenalty: (a, u, r, e) => `Amenities shortage: max(−50, 200/3 × ${a} / ${u}) = max(−50, ${r}) = ${e}`,
        conditionsFormulaNone: "Amenities exactly balanced (0 available): no effect on happiness.",
        conditionsInfoHappiness: "Happiness: starts at 50 (range 0 to 100). With surplus amenities it rises, up to +20 when there are twice as many as the pops use; with a shortage it drops, down to −50 when less than a quarter of the needed amenities exist. Only amenities and the manual extra happiness are counted: edicts, civics, traits, factions and events are not modelled.",
