        modifierStackTradeConversion: "各資源は、職業が産出した交易にそのレートを掛けた量を受け取ります。残る交易にも独自のレートがあります。帝国の倍率より前に適用されます。",
        modifierOrder4b: "貿易政策が、職業の交易価値を交換レートに従って各資源に振り分けます。",
        modifierOrder4a: "安定度の効果：惑星の安定度が職業の資源産出を増減させます（50を超える1ポイントごとに+0.6%、下回る1ポイントごとに−1%）。快適度には影響しません。",
