        conditionsStability: "安定度",
        conditionsFormulaApprovalHigh: (a, b) => `支持率 = 幸福度 = ${a}。50超：+0.6 × (${a} − 50)、切り捨て = ${b}`,
        conditionsFormulaApprovalLow: (a, b) => `支持率 = 幸福度 = ${a}。50未満：−1 × (50 − ${a}) = ${b}`,
        conditionsFormulaHousing: (m, r, p) => `住居：−40 × 不足 / 必要 = −40 × ${m} / ${r} = ${p}`,
        conditionsInfoStability: "安定度：基本は50（範囲0～100）。通常の帝国では、支持率が50を超える1ポイントごとに0.6加算し、下回る1ポイントごとに1減算します。ここではすべての人口を同じように扱うため、支持率は幸福度と同じです。ゲシュタルト帝国には幸福度がなく、快適度が同じ数値で安定度に直接作用します。法務執行官や兵士などの職業は安定度を加えます（修正値なので、安定度の効果では変化しません）。住居が不足すると、40 ×（不足している住居 / 必要な住居）を減算します。犯罪は表示されますが安定度は変えません。布告・派閥・イベントはモデル化していません（手動の追加安定度を使ってください）。",
        conditionsHappinessBase: "基本幸福度",
        conditionsHappinessAmenities: "快適さの効果",
        conditionsHappiness: "幸福度",
        conditionsHappinessNA: "ゲシュタルト帝国：幸福度はなく、快適さは安定度に直接作用します。",
        conditionsFormulaBonus: (a, u, r, e) => `快適さの余剰：min(20, 20 × ${a} / ${u}) = min(20, ${r}) = ${e}`,
        conditionsFormulaPenalty: (a, u, r, e) => `快適さの不足：max(−50, 200/3 × ${a} / ${u}) = max(−50, ${r}) = ${e}`,
        conditionsFormulaNone: "快適さがちょうど釣り合っています（利用可能 0）：幸福度への影響なし。",
        conditionsInfoHappiness: "幸福度：基本は50（範囲0～100）。快適度が余ると上昇し、人口の使用量の2倍あれば最大+20になります。不足すると低下し、必要量の4分の1未満なら最大−50になります。数えるのは快適度と手動の追加幸福度のみで、布告・国是・特性・派閥・イベントはモデル化していません。",
        conditionsHeading: "惑星の状態",
