        conditionsInfoPops: "人口：充足した職業1つにつき人口1に、手動入力の民間人（職業のない人口）を加えます。人口1は住居1を必要とし、快適度1を使います（Wikiの×100表記では100 = 人口1）。",
        conditionsInfoHousing: "住居：区域、首都、建造物が提供します。人口が住居を上回ると住居が不足し、安定度が下がります（安定度を参照）。",
        conditionsInfoAmenities: "利用可能な快適度 = 提供される快適度 −（5 + 人口の使用量）。どの植民地も常に5を失います。プラス = 余剰、マイナス = 不足です。建造物は最も近い整数に丸め、職業は切り捨てます。",
